import json
import numpy as np

theta = 0.5
rho = 0.5
d = 4
codes = np.arange(1001, dtype=float) / 1000.0

def node(l, u, a, b, c):
    return {'l': l, 'u': u, 'a': a, 'b': b, 'c': c}

def evaluate(t, x):
    if x == t['l']:
        return t['a']
    if x == t['u']:
        return t['b']
    h = (t['l'] + t['u']) / 2.0
    if 'm' not in t:
        delta = t['b'] - t['a']
        q = (t['a'] + t['b']) / 2.0
        force = theta * delta * delta / (1.0 + delta * delta) + rho * t['c'] * delta
        t['m'] = q + force
    if x == h:
        return t['m']
    assert t['u'] - t['l'] > 1.0 / d
    side = 'left' if x < h else 'right'
    if side not in t:
        force = t['m'] - (t['a'] + t['b']) / 2.0
        if side == 'left':
            t[side] = node(t['l'], h, t['a'], t['m'], force)
        else:
            t[side] = node(h, t['u'], t['m'], t['b'], force)
    return evaluate(t[side], x)

positions = [0.25, 0.5, 0.75]
first = node(0.0, 1.0, 0.0, 1.0, 0.0)
values = [evaluate(first, x) for x in positions]
second = node(0.0, 1.0, 0.0, 1.0, 0.0)
reverse = {x: evaluate(second, x) for x in reversed(positions)}
result = {
    'values': [round(v, 6) for v in values],
    'token_indices': [int(np.argmin(np.abs(codes - np.clip(v, codes.min(), codes.max())))) for v in values],
    'order_invariant': all(v == reverse[x] for x, v in zip(positions, values))
}
print(json.dumps(result, sort_keys=True))
